/*
    PWAInfo - خلاصهء پروژه‌های Project Web App (سازمان زمین‌شناسی)
    ===================================================================
    منبع: فایل Database\OrgSummary.xlsx (Sheet1، 570 سطر داده + سطر عنوان)
    تاریخ تولید اسکریپت: 1405/06/26 (2026-09-17)

    نگاشت ستون‌های اکسل به ستون‌های جدول:
      ردیف               -> حذف شد (در فایل کاملاً خالی بود؛ ID خودافزا جایگزین آن است)
      نام پروژه          -> ProjectName
      وضعیت              -> Status              ('در حال اجرا' | 'بدون وضعیت')
      پیشرفت برنامه ای   -> PlannedProgress     (درصد 0..100)
      پیشرفت واقعی       -> ActualProgress      (درصد 0..100)
      شروع               -> StartDateJ / StartDate
      پایان              -> FinishDateJ / FinishDate
      شروع برنامه ای     -> PlannedStartJ / PlannedStart
      پایان برنامه ای    -> PlannedFinishJ / PlannedFinish
      هزینه کل پروژه     -> TotalCost           (در فایل فعلی همهء مقادیر صفر است)
      نوع پروژه          -> ProjectType
      درصد تحقق          -> AchievementPct      (= پیشرفت واقعی / پیشرفت برنامه‌ای × 100)
      Project_Code       -> ProjectCode         (یکتا نیست؛ 4 کد تکراری و 137 مقدار خالی دارد)
      منطقه پروژه        -> Region
      نحوه اجرای پروژه   -> ExecutionMethod     ('امانی' | 'پیمانی')
      مدیر پروژه         -> ProjectManager
      ناظر پروژه         -> ProjectSupervisor
      سطح 1 سازمان       -> OrgLevel1
      سطح 2 سازمان       -> OrgLevel2
      (جدید)             -> Lat, Long           مختصات تقریبی پین پروژه؛ در اکسل نبود و از روی نام پروژه پر شده است

    نکته‌ها:
      * تاریخ‌ها در اکسل به‌صورت متن شمسی «yyyy/mm/dd» بودند. هر تاریخ در دو ستون نگهداری می‌شود:
        ستون *J (NCHAR(10)) همان متن شمسی برای نمایش، و ستون DATE معادل میلادی برای محاسبات
        (DATEDIFF، مقایسه با GETDATE() و ...). تبدیل شمسی→میلادی در زمان تولید اسکریپت انجام شده است.
      * ستون‌های محاسباتی (Computed) برای تحلیل اضافه شده‌اند و در اکسل وجود نداشتند:
          ProgressGap        = PlannedProgress - ActualProgress
          FinishSlipDays     = DATEDIFF(day, PlannedFinish, FinishDate)   (مثبت = تأخیر در پایان)
          DurationDays       = DATEDIFF(day, StartDate, FinishDate)
          TahaghoghCategory  = دستهء تحقق با همان کدهای GISInfo.TahaghoghRoute:
                               1 = بیش از 90٪  2 = 70 تا 90٪  3 = 50 تا 70٪  4 = کمتر از 50٪  5 = آغاز نشده
      * Lat / Long: از نام محل در انتهای عنوان پروژه (مثل «جیرفت - چاه قنبر») با سرویس OpenStreetMap Nominatim
        به‌دست آمده و تقریبی است. اگر محل پیدا نشد، مختصات مرکز منطقه گذاشته شده. مرجع اصلاح دستی:
        Database\PWAInfo_Locations.xlsx (ستون LocationSource: place = محل پیدا شد، region = مرکز منطقه).
        پروژه‌های هم‌مکان مختصات یکسان دارند و در نقشه یک پین می‌شوند (وب‌پارت ShowAllProjectInfo).
      * سازگار با SQL Server 2012 و بالاتر.
*/

SET NOCOUNT ON;
GO

IF OBJECT_ID(N'dbo.PWAInfo', N'U') IS NOT NULL
    DROP TABLE dbo.PWAInfo;
GO

CREATE TABLE dbo.PWAInfo
(
    ------------------------------------------------------------------
    -- هویت
    ------------------------------------------------------------------
    ID                  INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PWAInfo PRIMARY KEY,
    ProjectName         NVARCHAR(200)   NOT NULL,           -- نام پروژه (حداکثر طول در فایل: 140)
    ProjectCode         VARCHAR(20)     NULL,               -- Project_Code (9 تا 14 رقم؛ یکتا نیست)
    Status              NVARCHAR(50)    NULL,               -- وضعیت

    ------------------------------------------------------------------
    -- پیشرفت / تحقق
    ------------------------------------------------------------------
    PlannedProgress     DECIMAL(6,2)    NULL,               -- پیشرفت برنامه‌ای (٪)
    ActualProgress      DECIMAL(6,2)    NULL,               -- پیشرفت واقعی (٪)
    AchievementPct      DECIMAL(6,2)    NULL,               -- درصد تحقق (٪)؛ در فایل تا 103.91 دیده شد

    ------------------------------------------------------------------
    -- تاریخ‌ها (شمسی به‌صورت متن + میلادی برای محاسبه)
    ------------------------------------------------------------------
    StartDateJ          NCHAR(10)       NULL,               -- شروع (شمسی)
    StartDate           DATE            NULL,               -- شروع (میلادی)
    FinishDateJ         NCHAR(10)       NULL,               -- پایان (شمسی)
    FinishDate          DATE            NULL,               -- پایان (میلادی)
    PlannedStartJ       NCHAR(10)       NULL,               -- شروع برنامه‌ای (شمسی)
    PlannedStart        DATE            NULL,               -- شروع برنامه‌ای (میلادی)
    PlannedFinishJ      NCHAR(10)       NULL,               -- پایان برنامه‌ای (شمسی)
    PlannedFinish       DATE            NULL,               -- پایان برنامه‌ای (میلادی)

    ------------------------------------------------------------------
    -- مالی
    ------------------------------------------------------------------
    TotalCost           DECIMAL(18,2)   NULL,               -- هزینه کل پروژه

    ------------------------------------------------------------------
    -- دسته‌بندی / سازمان
    ------------------------------------------------------------------
    ProjectType         NVARCHAR(50)    NULL,               -- نوع پروژه (9 مقدار متمایز)
    Region              NVARCHAR(50)    NULL,               -- منطقه پروژه (24 مقدار متمایز)
    ExecutionMethod     NVARCHAR(20)    NULL,               -- نحوه اجرا: امانی | پیمانی
    ProjectManager      NVARCHAR(100)   NULL,               -- مدیر پروژه (شخص یا شرکت/پژوهشکده)
    ProjectSupervisor   NVARCHAR(100)   NULL,               -- ناظر پروژه
    OrgLevel1           NVARCHAR(150)   NULL,               -- سطح 1 سازمان
    OrgLevel2           NVARCHAR(150)   NULL,               -- سطح 2 سازمان

    ------------------------------------------------------------------
    -- موقعیت جغرافیایی پین پروژه (تقریبی؛ WGS84)
    ------------------------------------------------------------------
    Lat                 DECIMAL(9,6)    NULL,               -- عرض جغرافیایی
    [Long]              DECIMAL(9,6)    NULL,               -- طول جغرافیایی

    ------------------------------------------------------------------
    -- ستون‌های محاسباتی برای تحلیل
    ------------------------------------------------------------------
    ProgressGap         AS CAST(PlannedProgress - ActualProgress AS DECIMAL(6,2)) PERSISTED,
    FinishSlipDays      AS DATEDIFF(DAY, PlannedFinish, FinishDate),
    DurationDays        AS DATEDIFF(DAY, StartDate, FinishDate),
    TahaghoghCategory   AS CASE
                              WHEN ISNULL(ActualProgress,0) = 0  THEN 5
                              WHEN AchievementPct >  90          THEN 1
                              WHEN AchievementPct >  70          THEN 2
                              WHEN AchievementPct >  50          THEN 3
                              ELSE 4
                           END PERSISTED,

    CONSTRAINT CK_PWAInfo_Progress CHECK (PlannedProgress BETWEEN 0 AND 100 AND ActualProgress BETWEEN 0 AND 100)
);
GO

CREATE INDEX IX_PWAInfo_ProjectCode   ON dbo.PWAInfo (ProjectCode);
CREATE INDEX IX_PWAInfo_Region        ON dbo.PWAInfo (Region);
CREATE INDEX IX_PWAInfo_ProjectType   ON dbo.PWAInfo (ProjectType);
CREATE INDEX IX_PWAInfo_PlannedFinish ON dbo.PWAInfo (PlannedFinish) INCLUDE (ActualProgress);
CREATE INDEX IX_PWAInfo_Map           ON dbo.PWAInfo (ProjectType, Region) INCLUDE (Lat, [Long]);
GO

