------------------------------------------------------------------
-- کنترل کیفیت داده پس از درج
------------------------------------------------------------------
SELECT COUNT(*) AS TotalRows FROM dbo.PWAInfo;                       -- انتظار: 570

-- کدهای پروژهء تکراری (4 کد، 9 سطر)
SELECT ProjectCode, COUNT(*) AS Cnt
FROM dbo.PWAInfo WHERE ProjectCode IS NOT NULL
GROUP BY ProjectCode HAVING COUNT(*) > 1;

-- سطرهایی که کد داخل نام پروژه با ستون ProjectCode نمی‌خواند یا ستون خالی است
SELECT ID, ProjectName, ProjectCode
FROM dbo.PWAInfo
WHERE ProjectName LIKE N'%[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]%'
  AND (ProjectCode IS NULL OR ProjectName NOT LIKE N'%' + ProjectCode + N'%');

-- سطرهای تستی/بدون وضعیت که باید قبل از گزارش‌گیری حذف یا فیلتر شوند
SELECT ID, ProjectName, Status FROM dbo.PWAInfo
WHERE Status = N'بدون وضعیت' OR ProjectName LIKE N'%تست%';

-- پوشش مختصات: چند سطر مختصات دارند و چند نقطهء متمایز روی نقشه می‌افتد
SELECT COUNT(*) AS Rows_, COUNT(Lat) AS Rows_WithCoords,
       COUNT(DISTINCT CAST(Lat AS VARCHAR(20)) + ',' + CAST([Long] AS VARCHAR(20))) AS DistinctPoints
FROM dbo.PWAInfo;

-- پروژه‌های هم‌مکان (یک پین با چند پروژه در نقشه)
SELECT Lat, [Long], COUNT(*) AS Projects, MIN(Region) AS Region
FROM dbo.PWAInfo WHERE Lat IS NOT NULL
GROUP BY Lat, [Long] HAVING COUNT(*) > 1 ORDER BY Projects DESC;

------------------------------------------------------------------
-- تحلیل 1: وضعیت کلی پورتفولیو
------------------------------------------------------------------
SELECT
    COUNT(*)                                                        AS Projects,
    SUM(CASE WHEN ActualProgress >= 100 THEN 1 ELSE 0 END)          AS Completed,
    SUM(CASE WHEN ActualProgress  =   0 THEN 1 ELSE 0 END)          AS NotStarted,
    SUM(CASE WHEN PlannedFinish < CAST(GETDATE() AS DATE)
              AND ActualProgress < 100 THEN 1 ELSE 0 END)           AS OverduePlannedFinish,
    SUM(CASE WHEN FinishSlipDays > 0 THEN 1 ELSE 0 END)             AS FinishRescheduledLater,
    AVG(PlannedProgress)                                            AS AvgPlanned,
    AVG(ActualProgress)                                             AS AvgActual,
    AVG(ProgressGap)                                                AS AvgGap,
    AVG(CASE WHEN FinishSlipDays > 0 THEN FinishSlipDays END)       AS AvgSlipDaysWhenLate
FROM dbo.PWAInfo
WHERE Status = N'در حال اجرا';

------------------------------------------------------------------
-- تحلیل 2: توزیع فاصلهء برنامه/واقعی (ProgressGap)
------------------------------------------------------------------
SELECT
    CASE WHEN ProgressGap <= 0  THEN N'0- جلوتر یا برابر برنامه'
         WHEN ProgressGap <= 10 THEN N'1- تا 10 درصد عقب'
         WHEN ProgressGap <= 25 THEN N'2- 10 تا 25 درصد عقب'
         WHEN ProgressGap <= 50 THEN N'3- 25 تا 50 درصد عقب'
         ELSE                        N'4- بیش از 50 درصد عقب' END  AS GapBand,
    COUNT(*) AS Projects
FROM dbo.PWAInfo
WHERE Status = N'در حال اجرا'
GROUP BY CASE WHEN ProgressGap <= 0  THEN N'0- جلوتر یا برابر برنامه'
              WHEN ProgressGap <= 10 THEN N'1- تا 10 درصد عقب'
              WHEN ProgressGap <= 25 THEN N'2- 10 تا 25 درصد عقب'
              WHEN ProgressGap <= 50 THEN N'3- 25 تا 50 درصد عقب'
              ELSE                        N'4- بیش از 50 درصد عقب' END
ORDER BY GapBand;

------------------------------------------------------------------
-- تحلیل 3: دستهء تحقق (همان رنگ‌بندی نقشهء GISInfo)
------------------------------------------------------------------
SELECT TahaghoghCategory,
       CASE TahaghoghCategory WHEN 1 THEN N'بیش از 90٪ (سبز)' WHEN 2 THEN N'70 تا 90٪ (زرد)'
                              WHEN 3 THEN N'50 تا 70٪ (صورتی)' WHEN 4 THEN N'کمتر از 50٪ (قرمز)'
                              ELSE N'آغاز نشده' END AS CategoryTitle,
       COUNT(*) AS Projects
FROM dbo.PWAInfo
GROUP BY TahaghoghCategory ORDER BY TahaghoghCategory;

------------------------------------------------------------------
-- تحلیل 4: به تفکیک نوع پروژه
------------------------------------------------------------------
SELECT ISNULL(ProjectType, N'(خالی)') AS ProjectType,
       COUNT(*)                                 AS Projects,
       AVG(PlannedProgress)                     AS AvgPlanned,
       AVG(ActualProgress)                      AS AvgActual,
       AVG(ProgressGap)                         AS AvgGap,
       SUM(CASE WHEN PlannedFinish < CAST(GETDATE() AS DATE) AND ActualProgress < 100 THEN 1 ELSE 0 END) AS Overdue,
       SUM(CASE WHEN ActualProgress >= 100 THEN 1 ELSE 0 END) AS Completed
FROM dbo.PWAInfo
GROUP BY ProjectType ORDER BY Projects DESC;

------------------------------------------------------------------
-- تحلیل 5: به تفکیک منطقه (مرتب بر اساس بدترین فاصله)
------------------------------------------------------------------
SELECT ISNULL(Region, N'(خالی)') AS Region,
       COUNT(*)                  AS Projects,
       AVG(PlannedProgress)      AS AvgPlanned,
       AVG(ActualProgress)       AS AvgActual,
       AVG(ProgressGap)          AS AvgGap,
       SUM(CASE WHEN PlannedFinish < CAST(GETDATE() AS DATE) AND ActualProgress < 100 THEN 1 ELSE 0 END) AS Overdue,
       AVG(FinishSlipDays)       AS AvgSlipDays
FROM dbo.PWAInfo
GROUP BY Region ORDER BY AvgGap DESC;

------------------------------------------------------------------
-- تحلیل 6: امانی در برابر پیمانی
------------------------------------------------------------------
SELECT ExecutionMethod,
       COUNT(*)              AS Projects,
       AVG(PlannedProgress)  AS AvgPlanned,
       AVG(ActualProgress)   AS AvgActual,
       AVG(ProgressGap)      AS AvgGap,
       AVG(FinishSlipDays)   AS AvgSlipDays,
       SUM(CASE WHEN ActualProgress >= 100 THEN 1 ELSE 0 END) AS Completed
FROM dbo.PWAInfo
GROUP BY ExecutionMethod;

------------------------------------------------------------------
-- تحلیل 7: به تفکیک سال شروع (شمسی)
------------------------------------------------------------------
SELECT LEFT(StartDateJ, 4) AS StartYearJ,
       COUNT(*)            AS Projects,
       AVG(ActualProgress) AS AvgActual,
       SUM(CASE WHEN PlannedFinish < CAST(GETDATE() AS DATE) AND ActualProgress < 100 THEN 1 ELSE 0 END) AS Overdue
FROM dbo.PWAInfo
GROUP BY LEFT(StartDateJ, 4) ORDER BY StartYearJ;

------------------------------------------------------------------
-- تحلیل 8: 20 پروژهء بحرانی (بیشترین فاصله از برنامه)
------------------------------------------------------------------
SELECT TOP 20 ID, ProjectName, Region, ProjectType, ExecutionMethod,
       PlannedProgress, ActualProgress, ProgressGap,
       PlannedFinishJ, FinishDateJ, FinishSlipDays, ProjectManager
FROM dbo.PWAInfo
WHERE Status = N'در حال اجرا' AND ActualProgress < 100
ORDER BY ProgressGap DESC, FinishSlipDays DESC;

------------------------------------------------------------------
-- تحلیل 9: بار کاری مدیران پروژه (بیش از 2 پروژه)
------------------------------------------------------------------
SELECT ProjectManager, COUNT(*) AS Projects,
       AVG(ActualProgress) AS AvgActual, AVG(ProgressGap) AS AvgGap
FROM dbo.PWAInfo
WHERE ProjectManager IS NOT NULL
GROUP BY ProjectManager HAVING COUNT(*) > 2
ORDER BY Projects DESC;

------------------------------------------------------------------
-- تحلیل 10: کامل بودن داده‌ها (درصد خالی هر ستون)
------------------------------------------------------------------
SELECT
    CAST(100.0 * SUM(CASE WHEN ProjectCode       IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_ProjectCode,
    CAST(100.0 * SUM(CASE WHEN ProjectType       IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_ProjectType,
    CAST(100.0 * SUM(CASE WHEN Region            IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_Region,
    CAST(100.0 * SUM(CASE WHEN ProjectManager    IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_Manager,
    CAST(100.0 * SUM(CASE WHEN ProjectSupervisor IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_Supervisor,
    CAST(100.0 * SUM(CASE WHEN OrgLevel1         IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_OrgLevel1,
    CAST(100.0 * SUM(CASE WHEN OrgLevel2         IS NULL THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Null_OrgLevel2,
    CAST(100.0 * SUM(CASE WHEN TotalCost = 0     THEN 1 ELSE 0 END) / COUNT(*) AS DECIMAL(5,1)) AS Pct_Zero_TotalCost
FROM dbo.PWAInfo;
GO
